const documentViews=new Map();
async function openRemoteDocument(hostId,run,source){
  const parentId='peer:'+hostId+':'+run.id;
  const previous=ui.state.tabs.find(tab=>tab.type==='remote-document'&&tab.parentId===parentId&&tab.source===source);
  if(previous){ui.openTab(previous);return;}
  const pending=await mutate(hostId,'chat.documents.request',{id:run.id,source});
  const id='document:'+hostId+':'+run.id+':'+pending.documentId;
  documentViews.set(id,{requestId:pending.requestId,version:pending.version,enabled:false});
  ui.openTab({id,type:'remote-document',parentId,hostId,runId:run.id,documentId:pending.documentId,label:pending.title,mediaType:pending.mediaType,source});
}
export function forgetRemoteDocument(id){documentViews.delete(id);void window.desktop?.artifactPreview?.({action:'hide'}).catch(()=>{});}
