function editRemoteSchedule(hostId,s,reload,hostState={}){
  const owned=!!s.source?.manifest;let availableScheduleModels=null;
  ui.showDialog(`<h2>${esc(s.name)} · ${esc(hostLabel(hostId))}</h2><p class="note">${owned?'Repository-owned schedule. Edit its source manifest on this Mac.':'Changes are saved on this Mac with revision protection.'}</p><label>Name<input id="peer-schedule-name" value="${esc(s.name)}" ${owned?'disabled':''}></label><div class="row"><label>Cron<input id="peer-schedule-cron" value="${esc(s.cron)}" ${owned?'disabled':''}></label><label>Time zone<input id="peer-schedule-timezone" value="${esc(s.timezone)}" ${owned?'disabled':''}></label></div><div class="row"><label>Provider<select id="peer-schedule-provider" ${owned?'disabled':''}>${[...new Set([s.provider,...Object.keys(hostState.providerStatuses||{})])].filter(Boolean).map(id=>option(id,providerLabel(id),s.provider)).join('')}</select></label><label>Model<select id="peer-schedule-model" ${owned?'disabled':''}>${option(s.model||'',s.model||'Provider default',s.model||'')}</select></label></div><div id="peer-schedule-controls" class="row"></div><p id="peer-schedule-catalog" class="note"></p><label>After missed runs<select id="peer-schedule-misfire" ${owned?'disabled':''}>${option('skip','Wait for next time',s.misfire)}${option('coalesce','Catch up once',s.misfire)}</select></label><details><summary>Workspace context on ${esc(hostLabel(hostId))}</summary><label>Workspace<select id="peer-schedule-workspace" ${owned?'disabled':''}>${(hostState.context?.workspaces||[]).map(w=>option(w.id,w.name||w.label||w.id,s.contextSelection?.workspaceId||hostState.context?.defaultWorkspaceId)).join('')}</select></label><label class="checkbox-row"><input id="peer-schedule-defaults" type="checkbox" ${s.contextSelection?.includeDefaults!==false?'checked':''} ${owned?'disabled':''}>Include workspace defaults</label>${(hostState.context?.entries||[]).filter(e=>e.kind!=='agent').map(e=>`<label class="checkbox-row"><input type="checkbox" data-peer-schedule-source="${esc(e.id)}" ${s.contextSelection?.selectedIds?.includes(e.id)?'checked':''} ${owned||e.mode==='disabled'||e.missing?'disabled':''}>${esc(e.name)} · ${esc(e.kind)}</label>`).join('')}</details><label>Instructions<textarea id="peer-schedule-prompt" rows="5" ${owned?'disabled':''}>${esc(s.prompt)}</textarea></label><label class="checkbox-row"><input id="peer-schedule-enabled" type="checkbox" ${s.enabled?'checked':''} ${owned?'disabled':''}>Enabled</label><label class="checkbox-row"><input id="peer-schedule-notify" type="checkbox" ${s.notifications?.onCompletion?'checked':''} ${owned?'disabled':''}>Notify on completion</label><button id="peer-schedule-preview">Preview upcoming times</button><p id="peer-schedule-times" class="note"></p><div class="actions"><button id="close-dialog">Close</button><button id="peer-schedule-run">Run on ${esc(hostLabel(hostId))}</button>${owned?'':'<button id="dialog-submit">Save changes</button>'}</div>`,async()=>{if($('#peer-schedule-provider').value!==s.provider&&!availableScheduleModels?.some(model=>model.id===$('#peer-schedule-model').value))throw new Error('Choose an available model for the selected provider.');await mutate(hostId,'schedule.save',{id:s.id,expectedRevision:s.revision,changes:{provider:$('#peer-schedule-provider').value,model:$('#peer-schedule-model').value,...Object.fromEntries(['reasoningEffort','contextTier','serviceTier'].filter(key=>$('#peer-schedule-'+key)).map(key=>[key,$('#peer-schedule-'+key).value])),misfire:$('#peer-schedule-misfire').value,contextSelection:{...s.contextSelection,...($('#peer-schedule-workspace').value?{workspaceId:$('#peer-schedule-workspace').value}:{}),includeDefaults:$('#peer-schedule-defaults').checked,selectedIds:[...document.querySelectorAll('[data-peer-schedule-source]:checked')].map(input=>input.dataset.peerScheduleSource)},name:$('#peer-schedule-name').value,cron:$('#peer-schedule-cron').value,timezone:$('#peer-schedule-timezone').value,prompt:$('#peer-schedule-prompt').value,enabled:$('#peer-schedule-enabled').checked,notifications:{...s.notifications,onCompletion:$('#peer-schedule-notify').checked}}});void reload();});
  let catalogVersion=0;
  const catalog=async()=>{const version=++catalogVersion,provider=$('#peer-schedule-provider').value;availableScheduleModels=null;$('#peer-schedule-model').innerHTML=provider===s.provider?option(s.model||'',s.model||'Provider default',s.model||''):'<option value="">Choose a model</option>';$('#peer-schedule-controls').innerHTML='';try{const status=await request(hostId,'provider.status',{provider,force:false});if(version!==catalogVersion||!$('#peer-schedule-model'))return;const models=(status.models||[]).filter(model=>model.policy?.state!=='disabled');availableScheduleModels=models;if(!models.length){$('#peer-schedule-catalog').textContent=status.error||'Model metadata is unavailable on this Mac. Existing settings are preserved.';return;}$('#peer-schedule-catalog').textContent='Model capabilities reported by '+hostLabel(hostId)+'.';$('#peer-schedule-model').innerHTML='<option value="" disabled>Choose a model</option>'+(provider===s.provider&&s.model&&!models.some(m=>m.id===s.model)?option(s.model,s.model+' · saved',s.model):'')+models.map(model=>option(model.id,model.name||model.id,provider===s.provider?s.model:'')).join('');$('#peer-schedule-model').value=provider===s.provider?s.model||'':'';const controls=()=>{const model=models.find(m=>m.id===$('#peer-schedule-model').value);if(!model){$('#peer-schedule-controls').innerHTML='';return;}$('#peer-schedule-controls').innerHTML=[['reasoningEffort','Reasoning','reasoningEfforts'],['contextTier','Context','contextTiers'],['serviceTier','Speed','serviceTiers']].map(([key,label,field])=>`<label>${label}<select id="peer-schedule-${key}"><option value="">Provider default</option>${(model?.controls?.[field]||[]).map(v=>option(typeof v==='string'?v:v.id,typeof v==='string'?v:v.name||v.id,provider===s.provider&&model?.id===s.model?s[key]:'')).join('')}</select></label>`).join('');};$('#peer-schedule-model').onchange=controls;controls();}catch(error){if($('#peer-schedule-catalog'))$('#peer-schedule-catalog').textContent=error.message;}};
  if(!owned){$('#peer-schedule-provider').onchange=catalog;void catalog();}
  $('#peer-schedule-preview').onclick=async()=>{try{const value=await request(hostId,'schedule.preview',{cron:$('#peer-schedule-cron').value,timezone:$('#peer-schedule-timezone').value});if($('#peer-schedule-times'))$('#peer-schedule-times').textContent=(value.nextRuns||[]).map(date=>ui.time(date,$('#peer-schedule-timezone').value)).join('\n');}catch(error){ui.toast(error.message);}};
  $('#peer-schedule-run').onclick=async()=>{const button=$('#peer-schedule-run');button.disabled=true;try{const value=await mutate(hostId,'schedule.run',{id:s.id});$('#dialog').close();openPeerRun(hostId,value.runId,s.name);}catch(error){ui.toast(error.message);}finally{button.disabled=false;}};
}

function reuseRemoteMessage(key,entry){const input=$('#peer-followup');if(!input)return;if((input.value.trim()&&input.value!==entry.text||selectedAttachments('remote-run:'+key).length)&&!confirm('Replace the current unsent draft with this message?'))return;input.value=entry.text||'';drafts.set(key,input.value);input.focus();const restored=restoreSentAttachments('remote-run:'+key,entry.data?.delivery?.id);if((entry.data?.attachments?.length||0)>restored)ui.toast('Text restored. Some files are no longer available here; reattach them before sending.');}
